"""Random strings for the palindrome check: one line of ASCII.

Palindromes are built by mirroring half a string, so they are palindromes
before anything looks at them. The near-miss is one of those with a single
letter changed somewhere off centre -- close enough that a solution comparing
only the first and last characters still gets it wrong.
"""

LETTERS = "abcdefghijklmnopqrstuvwxyz"
PUNCTUATION = " ,.:;!-'"


def generate(rng, count):
    builders = (_palindrome, _near_miss, _punctuated, _digits)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _mirror(rng, half_length, alphabet=LETTERS):
    half = "".join(rng.choice(alphabet) for _ in range(half_length))
    middle = rng.choice(alphabet) if rng.random() < 0.5 else ""
    return half + middle + half[::-1]


def _palindrome(rng, index):
    return _case("a palindrome #%d" % index, _mirror(rng, rng.randint(3, 6)))


def _near_miss(rng, index):
    text = _mirror(rng, rng.randint(3, 6))
    # Any position except the middle character of an odd-length string, which
    # is its own mirror image and can be changed without breaking anything.
    middle = len(text) // 2 if len(text) % 2 else -1
    spoilt = rng.choice([i for i in range(len(text)) if i != middle])
    swap = rng.choice([c for c in LETTERS if c != text[spoilt]])
    return _case("one letter out #%d" % index,
                 text[:spoilt] + swap + text[spoilt + 1:],
                 "A palindrome with a single letter changed. The ends still "
                 "match; somewhere inside, they stop matching.")


def _punctuated(rng, index):
    text = _mirror(rng, rng.randint(3, 6))
    dressed = []
    for char in text:
        dressed.append(char.upper() if rng.random() < 0.5 else char)
        if rng.random() < 0.4:
            dressed.append(rng.choice(PUNCTUATION))
    return _case("punctuation and case #%d" % index, "".join(dressed).strip(),
                 "Skip anything that is not a letter or a digit, and compare "
                 "without regard to case.")


def _digits(rng, index):
    return _case("digits #%d" % index, _mirror(rng, rng.randint(2, 5), "0123456789"),
                 "Digits count as characters to compare, not as separators.")
